//! tree-sitter grammar for sprefa v5 `.dl` source.
//!
//! Generated by `tree-sitter generate` from `grammar.js`. The C parser lives
//! in `src/parser.c`; this crate exposes it as a `tree_sitter::Language` for
//! use from the LSP and any other tool that wants structured `.dl` parsing
//! with error recovery.

use tree_sitter_language::LanguageFn;

extern "C" {
    fn tree_sitter_dl() -> *const ::core::ffi::c_void;
}

/// Wrapper to match the `LanguageFn` signature (`*const ()` return).
unsafe extern "C" fn raw() -> *const () {
    tree_sitter_dl() as *const ()
}

/// Returns the tree-sitter language function for `.dl`.
pub fn language() -> LanguageFn {
    unsafe { LanguageFn::from_raw(raw) }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tree_sitter::Parser;

    fn errors(src: &str) -> Vec<(usize, usize, String)> {
        let mut p = Parser::new();
        p.set_language(&language().into()).unwrap();
        let tree = p.parse(src, None).unwrap();
        let mut out = Vec::new();
        let mut cursor = tree.walk();
        loop {
            let node = cursor.node();
            if node.is_error() {
                let (s, e) = (node.start_byte(), node.end_byte());
                let snippet = src.get(s..e).unwrap_or("").trim();
                let msg = if snippet.is_empty() {
                    "unexpected end of input".to_string()
                } else {
                    format!("unexpected: `{snippet}`")
                };
                out.push((s, e, msg));
            } else if node.is_missing() {
                let kind = node.kind();
                let pos = node.start_byte();
                out.push((pos, pos, format!("missing `{kind}`")));
            }
            if cursor.goto_first_child() {
                continue;
            }
            while !cursor.goto_next_sibling() {
                if !cursor.goto_parent() {
                    return out;
                }
            }
        }
    }

    #[test]
    fn parses_ban_example() {
        let src = include_str!("../test/ban.dl");
        let e = errors(src);
        assert!(e.is_empty(), "expected no parse errors, got: {e:?}");
    }

    #[test]
    fn parses_simple_rule() {
        let src = "rel edge(a: text, b: text).\nedge(\"a\", \"b\").\n? edge(x, y).\n";
        let e = errors(src);
        assert!(e.is_empty(), "expected no parse errors, got: {e:?}");
    }

    #[test]
    fn recovers_from_missing_paren() {
        let src = "rel t(a: text.\n";
        let e = errors(src);
        assert!(!e.is_empty(), "expected at least one error");
        assert!(e.iter().any(|(_, _, m)| m.contains("missing")),
            "expected a missing-token error, got: {e:?}");
    }

    #[test]
    fn parses_scan_and_sg() {
        let src = r#"rel diag(p: file, l: int).
diag(p, l) <- scan("WORK", "**/*.rs", p, r), sg(p, r, :rust, "dbg!($X)", l, c, el, ec).
? diag(p, l).
"#;
        let e = errors(src);
        assert!(e.is_empty(), "expected no parse errors, got: {e:?}");
    }
}
